package dev.presidencia;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;import net.minecraft.test.*;import net.minecraft.item.*;import net.minecraft.nbt.*;import net.minecraft.util.*;import net.minecraft.util.math.*;import net.minecraft.world.GameMode;
public class V03Tests implements FabricGameTest {
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=40) public void lastBulletRequiresFullCylinderSequence(TestContext c){
  var player=c.createMockPlayer(GameMode.SURVIVAL);var stack=new ItemStack(Terror.REVOLVER);player.setStackInHand(Hand.MAIN_HAND,stack);player.getInventory().insertStack(new ItemStack(Terror.BULLET,6));Terror.REVOLVER.reload(player,stack);var n=Gun.data(stack);n.putLong("ReloadEnd",c.getWorld().getTime());Gun.put(stack,n);Terror.REVOLVER.inventoryTick(stack,c.getWorld(),player,0,true);
  for(int i=0;i<5;i++){c.assertFalse(Gun.lastBonus(stack),"Early round not boosted");player.getItemCooldownManager().set(Terror.REVOLVER,0);Terror.REVOLVER.use(c.getWorld(),player,Hand.MAIN_HAND);}c.assertTrue(Gun.lastBonus(stack),"Sixth round boosted");
  c.assertEquals(Gun.shotDamage(false,true,false),18f,"Last body");c.assertEquals(Gun.shotDamage(true,true,false),25.5f,"Last HS");c.assertEquals(Gun.shotDamage(true,true,true),22f,"Lula exception");c.complete();
 }
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=30) public void partialReloadCannotEarnBonus(TestContext c){var p=c.createMockPlayer(GameMode.SURVIVAL);var stack=new ItemStack(Terror.REVOLVER);p.setStackInHand(Hand.MAIN_HAND,stack);p.getInventory().insertStack(new ItemStack(Terror.BULLET));Terror.REVOLVER.reload(p,stack);var n=Gun.data(stack);n.putLong("ReloadEnd",c.getWorld().getTime());Gun.put(stack,n);Terror.REVOLVER.inventoryTick(stack,c.getWorld(),p,0,true);c.assertFalse(Gun.lastBonus(stack),"One-round reload not boosted");c.complete();}
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=30) public void headVolumesExcludeMountHead(TestContext c){c.assertTrue(HeadRig.get("lula").hit(new Vec3d(0,43,-25),new Vec3d(0,43,25),"idle",0,null,0),"Head at authored height");c.assertFalse(HeadRig.get("lula").hit(new Vec3d(0,20,-25),new Vec3d(0,20,25),"idle",0,null,0),"Torso not head");c.assertTrue(HeadRig.get("lula_jumento").hit(new Vec3d(0,60,-25),new Vec3d(0,60,25),"mount_idle",0,null,0),"Mounted rider head");c.assertFalse(HeadRig.get("lula_jumento").hit(new Vec3d(0,25,-35),new Vec3d(0,25,35),"mount_idle",0,null,0),"Donkey not rider HS");c.complete();}
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=30) public void lulaLastHeadshotActuallyRemovesTwentyTwo(TestContext c){var p=c.createMockPlayer(GameMode.SURVIVAL);var lula=Terror.LULA.create(c.getWorld());lula.setPosition(Vec3d.ofBottomCenter(c.getAbsolutePos(new BlockPos(3,2,6))));lula.setNoGravity(true);lula.setAiDisabled(true);c.getWorld().spawnEntity(lula);p.setPosition(lula.getPos().add(0,43/16d-(p.getEyeY()-p.getY()),-5));p.setYaw(0);p.setPitch(0);var gun=new ItemStack(Terror.REVOLVER);Gun.rounds(gun,1);var n=Gun.data(gun);n.putBoolean("FullCycle",true);n.putInt("CycleShots",5);Gun.put(gun,n);p.setStackInHand(Hand.MAIN_HAND,gun);Terror.REVOLVER.use(c.getWorld(),p,Hand.MAIN_HAND);c.assertEquals(lula.getHealth(),478f,"Actual HS loss is 22");lula.discard();c.complete();}
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=30) public void managedStatePersistsAcrossNbt(TestContext c){var p=Terror.LULA.create(c.getWorld());p.managed=true;p.generation=9;p.followed=java.util.UUID.randomUUID();p.setHealth(321);var n=p.writeNbt(new NbtCompound());var restored=Terror.LULA.create(c.getWorld());restored.readNbt(n);c.assertTrue(restored.managed,"Managed identity");c.assertEquals(restored.generation,9,"Recovery generation");c.assertEquals(restored.followed,p.followed,"Owner retained");c.assertEquals(restored.getHealth(),321f,"No heal on restore");c.complete();}
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=35) public void damageNumberShowsRealValueAndExpires(TestContext c){var e=Terror.LULA.create(c.getWorld());e.setPosition(Vec3d.ofBottomCenter(c.getAbsolutePos(new BlockPos(2,2,2))));DamageNumbers.show(e,22,e.getPos(),true,true);var displays=c.getWorld().getEntitiesByClass(net.minecraft.entity.decoration.DisplayEntity.TextDisplayEntity.class,e.getBoundingBox().expand(2),d->true);c.assertTrue(displays.stream().anyMatch(d->d.getText().getString().equals("22 HS")),"Numeric text, not nominal shot damage");c.runAtTick(25,()->{c.assertTrue(displays.stream().allMatch(d->d.isRemoved()),"Text expires");c.complete();});}
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=35) public void sharedPairRecoveryAndVictory(TestContext c){
  var server=c.getWorld().getServer();StalkerDirector.reset(server);var player=c.createMockCreativeServerPlayerInWorld();var center=c.getAbsolutePos(new BlockPos(203,3,203));player.setPosition(Vec3d.ofBottomCenter(center));
  for(int x=-22;x<=22;x++)for(int z=-22;z<=22;z++)c.getWorld().setBlockState(center.add(x,-1,z),net.minecraft.block.Blocks.STONE.getDefaultState());
  StalkerDirector.step(server,java.util.List.of(player),1000);var list=c.getWorld().getEntitiesByType(Terror.LULA,p->p.managed&&p.isAlive());c.assertEquals(list.size(),1,"One automatic Lula");var lula=list.getFirst();lula.setHealth(321);StalkerDirector.checkpoint(lula);var saved=lula.writeNbt(new NbtCompound());int gen=lula.generation;lula.discard();
  StalkerDirector.step(server,java.util.List.of(player),1100);c.assertTrue(c.getWorld().getEntitiesByType(Terror.LULA,p->p.managed&&p.isAlive()).isEmpty(),"Recovery waits 30 seconds");
  StalkerDirector.step(server,java.util.List.of(player),1601);var restored=c.getWorld().getEntitiesByType(Terror.LULA,p->p.managed&&p.isAlive()).getFirst();c.assertEquals(restored.getHealth(),321f,"Recovery does not heal");c.assertTrue(restored.generation>gen,"Stale copy generation retired");
  var stale=Terror.LULA.create(c.getWorld());stale.readNbt(saved);stale.setUuid(java.util.UUID.randomUUID());c.getWorld().spawnEntity(stale);c.assertTrue(stale.isRemoved(),"Old unloaded generation rejected");
  var nether=server.getWorld(net.minecraft.world.World.NETHER);var moved=restored.teleportTo(new net.minecraft.world.TeleportTarget(nether,new Vec3d(0,90,0),Vec3d.ZERO,0,0,net.minecraft.world.TeleportTarget.ADD_PORTAL_CHUNK_TICKET));c.assertTrue(moved instanceof President,"Cross-dimension body transferred");
  StalkerDirector.step(server,java.util.List.of(player),2202);restored=c.getWorld().getEntitiesByType(Terror.LULA,p->p.managed&&p.isAlive()).getFirst();c.assertEquals(restored.getHealth(),321f,"Dimension recovery preserves damage");
  restored.damage(c.getWorld().getDamageSources().genericKill(),10000);StalkerDirector.step(server,java.util.List.of(player),2300);c.assertTrue(c.getWorld().getEntitiesByType(Terror.LULA,p->p.managed&&p.isAlive()).isEmpty(),"Defeated Lula does not respawn");
  StalkerDirector.reset(server);player.discard();c.complete();
 }
}
